function interpretTrainingBinaryRegressionV91(net){const t=net.trained,m=t.model,lastTr=t.trainHist.at(-1),lastVa=t.valHist.at(-1),evalData=prepareRows(State.split.test.length?State.split.test:State.split.val,m.stats).data,context=State.schema?.context||detectIndustrialContext(State.columns,targetY());let html=`<strong>${esc(context)}</strong><div class="decision-list">`;if(m.classification){const cm=classificationMetrics(m,evalData);html+=`<div class="decision-item"><strong>Recall ${(cm.Recall*100).toFixed(1)}%</strong><p>Indica qué fracción de los positivos reales detectó la red.</p></div><div class="decision-item"><strong>Precision ${(cm.Precision*100).toFixed(1)}%</strong><p>Indica cuántas alertas positivas fueron correctas.</p></div>`}else{const r=regressionMetrics(m,evalData),u=targetUnit();html+=`<div class="decision-item"><strong>MAE ${r.MAE.toFixed(3)}${u?' '+u:''}</strong><p>Distancia absoluta media entre predicción y realidad.</p></div><div class="decision-item"><strong>RMSE ${r.RMSE.toFixed(3)}${u?' '+u:''}</strong><p>Da mayor peso a errores grandes.</p></div><div class="decision-item"><strong>R² ${r.R2.toFixed(3)}</strong><p>${metricInterpretation('R²',r.R2,m)}</p></div>`}html+=`<div class="decision-item"><strong>Generalización</strong><p>${esc(interpretLearningCurve(t.trainHist,t.valHist))}</p></div></div>`;box.innerHTML=html;updateResultBacks();updateDecisionPanel();markFlowState()}

window.animateNetworkPass=async function(){const m=currentVisualModel();if(!m?.multiclass)return _v91.animateNetworkPass();if(State.animBusy)return;State.animBusy=true;const s=inspectorSample(m),tr=s.trace;clearPreviewActive();setNetworkMotion(`<strong>Fila ${s.rowNo}:</strong> forward multiclase con valores reales.`);for(let l=0;l<m.sizes.length;l++){if(l>0)applyActive(`.edge[data-edge-layer="${l-1}"]`);applyActive(`.svg-node[data-layer="${l}"]`);const val=tr.acts[l].slice(0,4).map(fmtN).join(', ');$('phaseLabel').textContent='FORWARD';$('phaseTitle').textContent=l===m.sizes.length-1?'Probabilidades Softmax':l===0?'Entradas X':`Capa H${l}`;$('phaseMath').textContent=l===m.sizes.length-1?`p = softmax(z) = [${val}${tr.acts[l].length>4?', …':''}]`:`a${l} = [${val}${tr.acts[l].length>4?', …':''}]`;await sleepAnim(240)}const pred=m.stats.classes[tr.predClass],pReal=tr.probs[s.yNorm]||1e-9,loss=-Math.log(Math.max(1e-9,pReal));$('phaseLabel').textContent='LOSS';$('phaseTitle').textContent=`Real: ${s.yRaw} · Predicha: ${pred}`;$('phaseMath').textContent=`CE = −log(p_clase_real)\n= ${fmtN(loss)}`;await sleepAnim(360);for(let l=m.sizes.length-2;l>=0;l--){applyActive(`.edge[data-edge-layer="${l}"]`,'back');$('phaseLabel').textContent='BACKPROP';$('phaseTitle').textContent='Gradiente de Cross-Entropy';$('phaseMath').textContent='δ_salida = p − one_hot(y)';await sleepAnim(190)}clearPreviewActive();setNetworkMotion(`Predicción: ${esc(pred)} · p(clase real) ${(pReal*100).toFixed(1)}% · CE ${fmtN(loss)}.`);State.animBusy=false};

function drawBarChartV91(cv,items,label){if(!cv)return;const c=clear(cv),p=canvasPalette(),w=cv.width,h=cv.height,pad={l:58,r:22,t:28,b:72};if(!items.length){c.fillStyle=p.muted;c.font='20px Segoe UI';c.fillText('Entrena al menos una red.',30,50);return}const max=Math.max(...items.map(x=>x.value),1e-9),bw=(w-pad.l-pad.r)/items.length;c.strokeStyle=p.line;c.beginPath();c.moveTo(pad.l,pad.t);c.lineTo(pad.l,h-pad.b);c.lineTo(w-pad.r,h-pad.b);c.stroke();items.forEach((it,i)=>{const bh=it.value/max*(h-pad.t-pad.b-20),x=pad.l+i*bw+bw*.16,y=h-pad.b-bh;c.fillStyle=[p.navy,p.violet,p.emerald,p.amber,p.red,p.steel][i%6];c.fillRect(x,y,bw*.68,bh);c.fillStyle=p.ink;c.font='17px Segoe UI';c.textAlign='center';c.fillText(fmtN(it.value),x+bw*.34,Math.max(20,y-7));c.save();c.translate(x+bw*.34,h-pad.b+15);c.rotate(-.35);c.fillStyle=p.muted;c.font='15px Segoe UI';c.textAlign='right';c.fillText(it.name.slice(0,18),0,0);c.restore()});c.fillStyle=p.muted;c.textAlign='left';c.font='16px Segoe UI';c.fillText(label,10,18)}
window.renderComparison=function(){const box=$('comparisonTable');if(!box)return;const rows=[];State.networks.forEach(n=>{const t=n.trained;if(!t)return;const m=t.model,s=t.settings||{},sizes=m.sizes||[numericX().length,...n.hidden,1];let params=0;for(let i=0;i<sizes.length-1;i++)params+=sizes[i]*sizes[i+1]+sizes[i+1];let metric='Test loss',value=t.testLoss;if(m.multiclass){const d=prepareMulticlassRowsV91(State.split.test.length?State.split.test:State.split.val,m.stats).data,me=mcMetricsV91(m,d);metric='1 − Accuracy';value=1-me.Accuracy}else if(m.classification){const d=prepareRows(State.split.test.length?State.split.test:State.split.val,m.stats).data,me=classificationMetrics(m,d);metric='1 − F1';value=1-me.F1}else{const d=prepareRows(State.split.test.length?State.split.test:State.split.val,m.stats).data,me=regressionMetrics(m,d);metric='RMSE';value=me.RMSE}rows.push({name:n.name,architecture:sizes.join('→'),opt:s.opt||'—',loss:s.lossType||'—',metric,value,params,diag:interpretLearningCurve(t.trainHist,t.valHist)})});box.innerHTML='<table><thead><tr><th>Red</th><th>Arquitectura</th><th>Optimizador</th><th>Loss</th><th>Métrica de evaluación</th><th>Valor</th><th>Parámetros</th><th>Generalización</th></tr></thead><tbody>'+rows.map(r=>`<tr><td>${esc(r.name)}</td><td>${esc(r.architecture)}</td><td>${esc(r.opt.toUpperCase())}</td><td>${esc(r.loss.toUpperCase())}</td><td>${esc(r.metric)}</td><td>${fmtN(r.value)}</td><td>${r.params}</td><td>${esc(r.diag)}</td></tr>`).join('')+'</tbody></table><p class="note">No hay “ganadora” automática. Para regresión se compara RMSE; para clasificación se representa error como 1−F1 o 1−Accuracy. Contrasta además complejidad, estabilidad y costo industrial del error.</p>';drawBarChartV91($('networkErrorComparisonChart'),rows.map(r=>({name:r.name,value:r.value})),rows[0]?.metric||'Error');drawBarChartV91($('networkComplexityChart'),rows.map(r=>({name:r.name,value:r.params})),'Parámetros')};

window.optimizerDemoStep=function(){const o=State.optimizerDemo,type=$('optimizerDemoSelect').value,g=o.g,lr=o.lr;o.t++;$('optWeight').textContent=o.w.toFixed(4);let formula='';if(type==='sgd'){o.w-=lr*g;formula='w ← w − ηg'}else if(type==='momentum'){o.v=.9*o.v-lr*g;o.w+=o.v;formula='v ← βv − ηg ; w ← w + v'}else if(type==='nesterov'){const old=o.v;o.v=.9*o.v-lr*g;o.w+=-.9*old+1.9*o.v;formula='Nesterov: gradiente anticipado + momentum'}else if(type==='adagrad'){o.s+=g*g;o.w-=lr*g/(Math.sqrt(o.s)+1e-8);formula='G ← G+g² ; w ← w−ηg/(√G+ε)'}else if(type==='rmsprop'){o.s=.9*o.s+.1*g*g;o.w-=lr*g/(Math.sqrt(o.s)+1e-8);formula='S ← βS+(1−β)g²'}else if(type==='adam'||type==='adamw'){o.m=.9*o.m+.1*g;o.s=.999*o.s+.001*g*g;const mh=o.m/(1-.9**o.t),vh=o.s/(1-.999**o.t);if(type==='adamw')o.w*=1-lr*.01;o.w-=lr*mh/(Math.sqrt(vh)+1e-8);formula=type==='adam'?'Adam: momentos m y v con corrección de sesgo':'AdamW: Adam + weight decay desacoplado'}else if(type==='adamax'){o.m=.9*o.m+.1*g;o.u=Math.max(.999*(o.u||0),Math.abs(g));o.w-=lr/(1-.9**o.t)*o.m/(o.u+1e-8);formula='AdaMax: norma infinito de gradientes acumulados'}$('optNewWeight').textContent=o.w.toFixed(6);$('optimizerFormula').textContent=formula};
window.renderOptimizerFormula=function(){const t=$('optimizerDemoSelect')?.value,f={sgd:'SGD: w ← w − ηg',momentum:'Momentum: v ← βv − ηg ; w ← w + v',nesterov:'Nesterov: evalúa el gradiente en una posición anticipada por el momentum.',adagrad:'AdaGrad: acumula Σg² y reduce progresivamente el paso.',rmsprop:'RMSProp: usa promedio móvil de g² para adaptar el paso.',adam:'Adam: combina primer y segundo momento del gradiente.',adamw:'AdamW: Adam + weight decay desacoplado.',adamax:'AdaMax: variante de Adam basada en la norma infinito.'};if($('optimizerFormula'))$('optimizerFormula').textContent=f[t]||''};
function optimizerChartInteractV91(e){const cv=$('optimizerComparisonChart'),data=State.optimizerCompareData;if(!cv||!data)return;const rect=cv.getBoundingClientRect(),cx=(e.touches?.[0]?.clientX??e.clientX)-rect.left,ratio=Math.max(0,Math.min(1,(cx/rect.width))),steps=(Object.values(data)[0]?.length||1)-1,step=Math.round(ratio*steps),vis=State.optimizerVisibility||{},vals=Object.entries(data).filter(([k])=>vis[k]!==false).map(([k,a])=>[k,a[step]]),text=`Paso ${step}: `+vals.map(([k,v])=>`${k.toUpperCase()} ${fmtN(v)}`).join(' · ');if($('optimizerStepReadout'))$('optimizerStepReadout').textContent=text;const tt=$('optimizerChartTooltip');if(tt){tt.hidden=false;tt.style.left=Math.max(0,Math.min(rect.width-230,cx))+'px';tt.style.top=((e.touches?.[0]?.clientY??e.clientY)-rect.top)+'px';tt.innerHTML=`<strong>Paso ${step}</strong><br>${vals.map(([k,v])=>`${k.toUpperCase()}: ${fmtN(v)}`).join('<br>')}`}}

function logGammaV91(z){const c=[676.5203681218851,-1259.1392167224028,771.32342877765313,-176.61502916214059,12.507343278686905,-.13857109526572012,9.984369578019571e-6,1.5056327351493116e-7];if(z<.5)return Math.log(Math.PI)-Math.log(Math.sin(Math.PI*z))-logGammaV91(1-z);z-=1;let x=.99999999999980993;for(let i=0;i<c.length;i++)x+=c[i]/(z+i+1);const t=z+c.length-.5;return .5*Math.log(2*Math.PI)+(z+.5)*Math.log(t)-t+Math.log(x)}
function betacfV91(a,b,x){const MAX=120,EPS=3e-10,FPMIN=1e-30;let qab=a+b,qap=a+1,qam=a-1,c=1,d=1-qab*x/qap;if(Math.abs(d)<FPMIN)d=FPMIN;d=1/d;let h=d;for(let m=1;m<=MAX;m++){let m2=2*m,aa=m*(b-m)*x/((qam+m2)*(a+m2));d=1+aa*d;if(Math.abs(d)<FPMIN)d=FPMIN;c=1+aa/c;if(Math.abs(c)<FPMIN)c=FPMIN;d=1/d;h*=d*c;aa=-(a+m)*(qab+m)*x/((a+m2)*(qap+m2));d=1+aa*d;if(Math.abs(d)<FPMIN)d=FPMIN;c=1+aa/c;if(Math.abs(c)<FPMIN)c=FPMIN;d=1/d;const del=d*c;h*=del;if(Math.abs(del-1)<EPS)break}return h}
function ibetaV91(x,a,b){if(x<=0)return 0;if(x>=1)return 1;const bt=Math.exp(logGammaV91(a+b)-logGammaV91(a)-logGammaV91(b)+a*Math.log(x)+b*Math.log(1-x));return x<(a+1)/(a+b+2)?bt*betacfV91(a,b,x)/a:1-bt*betacfV91(b,a,1-x)/b}
function fSurvivalV91(F,d1,d2){if(!Number.isFinite(F)||F<0)return NaN;const x=d1*F/(d1*F+d2);return Math.max(0,Math.min(1,1-ibetaV91(x,d1/2,d2/2)))}
function gammaQv91(a,x){if(x<0||a<=0)return NaN;const IT=160,EPS=3e-10;if(x<a+1){let ap=a,sum=1/a,del=sum;for(let n=1;n<=IT;n++){ap++;del*=x/ap;sum+=del;if(Math.abs(del)<Math.abs(sum)*EPS)break}const P=sum*Math.exp(-x+a*Math.log(x)-logGammaV91(a));return 1-P}let b=x+1-a,c=1/1e-30,d=1/b,h=d;for(let i=1;i<=IT;i++){const an=-i*(i-a);b+=2;d=an*d+b;if(Math.abs(d)<1e-30)d=1e-30;c=b+an/c;if(Math.abs(c)<1e-30)c=1e-30;d=1/d;const del=d*c;h*=del;if(Math.abs(del-1)<EPS)break}return Math.exp(-x+a*Math.log(x)-logGammaV91(a))*h}
function anovaV91(groups){const arr=Object.values(groups).filter(g=>g.length>=2),N=arr.reduce((s,g)=>s+g.length,0),k=arr.length,grand=arr.reduce((s,g)=>s+g.reduce((a,b)=>a+b,0),0)/N,ssb=arr.reduce((s,g)=>s+g.length*(mean(g)-grand)**2,0),ssw=arr.reduce((s,g)=>s+g.reduce((q,v)=>q+(v-mean(g))**2,0),0),df1=k-1,df2=N-k,F=(ssb/df1)/(ssw/df2);return{test:'ANOVA de una vía',stat:F,df1,df2,p:fSurvivalV91(F,df1,df2)}}
function welchAnovaV91(groups){const arr=Object.values(groups).filter(g=>g.length>=2),k=arr.length,stats=arr.map(g=>({n:g.length,m:mean(g),v:Math.max(1e-12,std(g)**2)})),w=stats.map(s=>s.n/s.v),W=w.reduce((a,b)=>a+b,0),mw=stats.reduce((s,x,i)=>s+w[i]*x.m,0)/W,num=stats.reduce((s,x,i)=>s+w[i]*(x.m-mw)**2,0)/(k-1),A=stats.reduce((s,x,i)=>s+(1-w[i]/W)**2/(x.n-1),0),den=1+(2*(k-2)/(k*k-1))*A,F=num/den,df1=k-1,df2=(k*k-1)/(3*A);return{test:'ANOVA de Welch',stat:F,df1,df2,p:fSurvivalV91(F,df1,df2)}}
function chiSquareV91(a,b){const ra=[...new Set(State.rows.map(r=>String(r[a]??'').trim()).filter(Boolean))],cb=[...new Set(State.rows.map(r=>String(r[b]??'').trim()).filter(Boolean))],counts=ra.map(()=>cb.map(()=>0));State.rows.forEach(r=>{const i=ra.indexOf(String(r[a]??'').trim()),j=cb.indexOf(String(r[b]??'').trim());if(i>=0&&j>=0)counts[i][j]++});const total=counts.flat().reduce((s,v)=>s+v,0),rt=counts.map(r=>r.reduce((s,v)=>s+v,0)),ct=cb.map((_,j)=>counts.reduce((s,r)=>s+r[j],0));let chi=0,low=0;counts.forEach((r,i)=>r.forEach((v,j)=>{const e=rt[i]*ct[j]/Math.max(1,total);if(e<5)low++;if(e>0)chi+=(v-e)**2/e}));const df=(ra.length-1)*(cb.length-1),p=gammaQv91(df/2,chi/2);return{test:'Chi-cuadrado de independencia',stat:chi,df1:df,df2:null,p,low}}
function drawGroupBoxplotsV91(groups){const cv=$('groupBoxplotCanvas');if(!cv)return;const c=clear(cv),p=canvasPalette(),entries=Object.entries(groups).filter(([,v])=>v.length);if(!entries.length)return;const all=entries.flatMap(([,v])=>v),min=Math.min(...all),max=Math.max(...all),w=cv.width,h=cv.height,pad={l:75,r:25,t:30,b:70},gw=(w-pad.l-pad.r)/entries.length,sy=v=>h-pad.b-(v-min)/(max-min||1)*(h-pad.t-pad.b);c.strokeStyle=p.line;c.beginPath();c.moveTo(pad.l,pad.t);c.lineTo(pad.l,h-pad.b);c.lineTo(w-pad.r,h-pad.b);c.stroke();entries.slice(0,12).forEach(([name,a],i)=>{const q1=quantile(a,.25),q2=quantile(a,.5),q3=quantile(a,.75),iqr=q3-q1,lo=Math.max(min,q1-1.5*iqr),hi=Math.min(max,q3+1.5*iqr),x=pad.l+i*gw+gw*.2,bw=gw*.6;c.strokeStyle=p.violet;c.fillStyle=colorWithAlpha(p.violet,.12);c.fillRect(x,sy(q3),bw,Math.max(2,sy(q1)-sy(q3)));c.strokeRect(x,sy(q3),bw,Math.max(2,sy(q1)-sy(q3)));c.strokeStyle=p.amber;c.beginPath();c.moveTo(x,sy(q2));c.lineTo(x+bw,sy(q2));c.stroke();c.strokeStyle=p.steel;c.beginPath();c.moveTo(x+bw/2,sy(lo));c.lineTo(x+bw/2,sy(hi));c.stroke();c.save();c.translate(x+bw/2,h-pad.b+14);c.rotate(-.4);c.fillStyle=p.muted;c.font='14px Segoe UI';c.textAlign='right';c.fillText(name.slice(0,16),0,0);c.restore()})}
function runStatTestV91(){const a=$('statsSelect')?.value,b=$('statsSecondSelect')?.value,box=$('statTestResult');if(!a||!b||!box){notify('Selecciona dos variables.','warning');return}const na=isNumericColumn(a),nb=isNumericColumn(b);if(na&&nb){box.innerHTML='<strong>No corresponde ANOVA/Chi-cuadrado.</strong><p>Ambas variables son numéricas. Usa Pearson/Spearman y revisa el scatter; un p-value no reemplaza tamaño de efecto ni contexto.</p>';return}if(na!==nb){const cat=na?b:a,num=na?a:b,groups={};State.rows.forEach(r=>{const k=String(r[cat]??'').trim(),v=Number(r[num]);if(k&&Number.isFinite(v))(groups[k]||(groups[k]=[])).push(v)});const eligible=Object.fromEntries(Object.entries(groups).filter(([,g])=>g.length>=2));if(Object.keys(eligible).length<2){box.innerHTML='<strong>Datos insuficientes.</strong><p>Se necesitan al menos dos grupos con dos observaciones válidas cada uno.</p>';return}const vars=Object.values(eligible).map(g=>std(g)**2).filter(v=>v>0),ratio=vars.length?Math.max(...vars)/Math.max(1e-12,Math.min(...vars)):Infinity,useWelch=ratio>4,res=useWelch?welchAnovaV91(eligible):anovaV91(eligible);drawGroupBoxplotsV91(eligible);box.innerHTML=`<strong>${res.test}</strong><div class="stat-test-result"><div><span>Estadístico F</span><b>${fmtN(res.stat)}</b></div><div><span>gl1</span><b>${fmtN(res.df1)}</b></div><div><span>gl2</span><b>${fmtN(res.df2)}</b></div><div><span>p-value</span><b>${res.p<.0001?'&lt; 0.0001':fmtN(res.p)}</b></div></div><ul class="assumption-list"><li>Observaciones independientes según el diseño del estudio.</li><li>Revisa QQ/forma dentro de cada grupo, especialmente con muestras pequeñas.</li><li>Razón de varianzas máx/mín ≈ ${fmtN(ratio)}; ${useWelch?'se usa Welch por heterogeneidad apreciable.':'ANOVA clásico se usa como aproximación al no observar gran heterogeneidad de varianzas.'}</li></ul><p class="note">Un p-value pequeño indica evidencia de diferencias de medias, no cuál grupo causa el resultado ni si la diferencia es operacionalmente importante.</p>`;return}const res=chiSquareV91(a,b);box.innerHTML=`<strong>${res.test}</strong><div class="stat-test-result"><div><span>χ²</span><b>${fmtN(res.stat)}</b></div><div><span>gl</span><b>${res.df1}</b></div><div><span>p-value</span><b>${res.p<.0001?'&lt; 0.0001':fmtN(res.p)}</b></div><div><span>Celdas esperadas &lt;5</span><b>${res.low}</b></div></div><ul class="assumption-list"><li>Observaciones independientes.</li><li>Las categorías deben ser mutuamente excluyentes.</li><li>${res.low?'Hay conteos esperados bajos: la aproximación Chi-cuadrado puede ser débil.':'No aparece la alerta básica de conteos esperados bajos.'}</li></ul><p class="note">La asociación estadística no implica causalidad.</p>`}
