/* Batch Normalization real para la ruta JS.
   Se activa solo cuando una capa oculta tiene batchNorm=true. */
function batchNormRequestedV91(){return !!currentNet()?.layerSettings?.some(s=>s.batchNorm)}
function attachBatchNormV91(m){
  m.bnLayers=(m.layerSettings||[]).map((ls,l)=>ls?.batchNorm?{
    gamma:Array(m.sizes[l+1]).fill(1),beta:Array(m.sizes[l+1]).fill(0),
    runningMean:Array(m.sizes[l+1]).fill(0),runningVar:Array(m.sizes[l+1]).fill(1),eps:1e-5,momentum:.9
  }:null);
  m.usesBatchNorm=m.bnLayers.some(Boolean);return m
}
function modelHasBatchNormV91(m){return !!m?.usesBatchNorm&&m.bnLayers?.some(Boolean)}
function forwardBNInferenceV91(m,x){
  const acts=[x],masks=[],raws=[],zs=[];let prev=x;
  for(let l=0;l<m.sizes.length-2;l++){
    const ls=m.layerSettings?.[l]||{},type=ls.activation||m.hiddenActivation,bn=m.bnLayers?.[l];
    const z=m.weights[l].map((row,j)=>row.reduce((q,w,i)=>q+w*prev[i],ls.bias===false?0:m.biases[l][j]));
    const u=bn?z.map((v,j)=>bn.gamma[j]*(v-bn.runningMean[j])/Math.sqrt(Math.max(bn.eps,bn.runningVar[j]+bn.eps))+bn.beta[j]):z;
    const a=u.map(v=>activation(v,type));raws.push(a.slice());zs.push(u.slice());masks.push(a.map(()=>1));acts.push(a);prev=a;
  }
  const L=m.sizes.length-2;
  const zo=m.weights[L].map((row,j)=>row.reduce((q,w,i)=>q+w*prev[i],m.biases[L][j]));
  if(m.multiclass){const probs=softmaxV91(zo);acts.push(probs);return{acts,masks,raws,zs,probs,y:Math.max(...probs),predClass:probs.indexOf(Math.max(...probs))}}
  const out=m.classification?1/(1+Math.exp(-Math.max(-40,Math.min(40,zo[0])))):zo[0];acts.push([out]);return{acts,masks,raws,zs,y:out}
}
function forwardTraceBNV91(m,x){
  let prev=x;const acts=[x],layers=[];
  for(let l=0;l<m.sizes.length-2;l++){
    const ls=m.layerSettings?.[l]||{},type=ls.activation||m.hiddenActivation,bn=m.bnLayers?.[l];
    const z=m.weights[l].map((row,j)=>row.reduce((q,w,i)=>q+w*prev[i],ls.bias===false?0:m.biases[l][j]));
    const u=bn?z.map((v,j)=>bn.gamma[j]*(v-bn.runningMean[j])/Math.sqrt(Math.max(bn.eps,bn.runningVar[j]+bn.eps))+bn.beta[j]):z;
    const a=u.map(v=>activation(v,type));layers.push({z:u,a,type,biases:m.biases[l],weights:m.weights[l],prev,batchNorm:!!bn,rawZ:z});acts.push(a);prev=a
  }
  const L=m.sizes.length-2,z=m.weights[L].map((row,j)=>row.reduce((q,w,i)=>q+w*prev[i],m.biases[L][j]));
  if(m.multiclass){const a=softmaxV91(z);layers.push({z,a,type:'softmax',biases:m.biases[L],weights:m.weights[L],prev});acts.push(a);return{acts,layers,probs:a,y:Math.max(...a),predClass:a.indexOf(Math.max(...a))}}
  const out=m.classification?1/(1+Math.exp(-Math.max(-40,Math.min(40,z[0])))):z[0];layers.push({z,a:[out],type:m.classification?'sigmoid':'linear',biases:m.biases[L],weights:m.weights[L],prev});acts.push([out]);return{acts,layers,y:out}
}
